"""Four original RGB source cameras for C179789 speed/conditions capture."""
from contextlib import contextmanager

PROFILE = {'overview': (1920, 1080), 'approach': (1280, 720),
           'reference_corner': (1280, 720), 'driver_reference': (1280, 720)}


@contextmanager
def source_cameras(world, ego, transforms, plan):
    rows = {row['name']: row for row in plan}
    if set(rows) != set(PROFILE) or set(transforms) != set(PROFILE):
        raise ValueError('All four named source cameras required')
    sensors = {}
    try:
        for name, size in PROFILE.items():
            row = rows[name]
            if (row.get('width'), row.get('height')) != size:
                raise ValueError('Pinned source camera dimensions required')
            fov = row.get('fov_deg')
            if type(fov) not in (int, float) or not 30 <= fov <= 120:
                raise ValueError('Source camera FOV required')
            blueprint = world.get_blueprint_library().find('sensor.camera.rgb')
            for key, value in [('image_size_x', size[0]), ('image_size_y', size[1]),
                               ('fov', fov), ('sensor_tick', 0.05)]:
                blueprint.set_attribute(key, str(value))
            kwargs = {'attach_to': ego} if name == 'driver_reference' else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError('Native camera spawn failed: ' + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""Spawn an actual Native lead vehicle on the source-reviewed ego lane."""

from contextlib import contextmanager
import math


def _project(point,tangent):
    return point.x*tangent[0]+point.y*tangent[1]


@contextmanager
def spawn_lead_traffic(world,ego,blueprint,transform,road_id,lane_id,lane_forward_xy):
    tx,ty=map(float,lane_forward_xy)
    norm=math.hypot(tx,ty)
    if not math.isfinite(norm) or norm<=0:raise ValueError("Invalid source lane direction")
    tangent=(tx/norm,ty/norm)
    lead=world.try_spawn_actor(blueprint,transform)
    if lead is None:raise ValueError("Native lead-traffic spawn failed")
    try:
        waypoint=world.get_map().get_waypoint(lead.get_location(),project_to_road=False)
        if waypoint is None or (waypoint.road_id,waypoint.lane_id)!=(road_id,lane_id):
            raise ValueError("Lead traffic outside source-reviewed ego lane")
        ego_position=_project(ego.get_location(),tangent)
        lead_position=_project(lead.get_location(),tangent)
        ego_half=float(ego.bounding_box.extent.x)
        lead_half=float(lead.bounding_box.extent.x)
        gap=lead_position-lead_half-(ego_position+ego_half)
        if not math.isfinite(gap) or gap<=0:
            raise ValueError("Lead vehicle does not begin ahead without overlap")
        yield {"actor":lead,"initial_longitudinal_body_gap_m":gap,
               "road_id":road_id,"lane_id":lane_id}
    finally:
        lead.destroy()

"""Bounded longitudinal control for the two sourced Native vehicles.

Target speeds and gaps are construction inputs, never legal speed limits.
Observed speed and body gap remain source measurements after capture.
"""
import math


def _positive(value, label, *, zero=False):
    if type(value) not in (int, float) or not math.isfinite(value) or (value < 0 if zero else value <= 0):
        raise ValueError("Finite positive " + label + " required")
    return float(value)


class LongitudinalController:
    def __init__(self, target_speed_mps, *, minimum_body_gap_m=4.0,
                 approach_body_gap_m=12.0, gain=0.2):
        self.target = _positive(target_speed_mps, "target speed", zero=True)
        self.minimum_gap = _positive(minimum_body_gap_m, "minimum body gap")
        self.approach_gap = _positive(approach_body_gap_m, "approach body gap")
        self.gain = _positive(gain, "speed gain")
        if self.approach_gap <= self.minimum_gap:
            raise ValueError("Approach gap must exceed minimum body gap")

    def step(self, speed_mps, *, lead_body_gap_m=None):
        speed = _positive(speed_mps, "observed speed", zero=True)
        if lead_body_gap_m is not None:
            gap = _positive(lead_body_gap_m, "observed body gap", zero=True)
            if gap <= self.minimum_gap:
                return {"throttle": 0.0, "brake": 1.0, "gap_guard": "emergency"}
            if gap <= self.approach_gap:
                ratio = (gap - self.minimum_gap) / (self.approach_gap - self.minimum_gap)
                allowed_speed = self.target * ratio
                if speed > allowed_speed:
                    return {"throttle": 0.0, "brake": min(1.0, .2 + (speed - allowed_speed) * self.gain),
                            "gap_guard": "approach"}
        error = self.target - speed
        if error <= 0:
            return {"throttle": 0.0, "brake": min(1.0, -error * self.gain),
                    "gap_guard": "clear"}
        return {"throttle": min(.45, error * self.gain), "brake": 0.0,
                "gap_guard": "clear"}

"""Measure speed with frame-specific traffic, surface, width and weather.

The stopping-distance calculation is a declared engineering diagnostic. It is
not a statutory definition of 'reasonable or proper'.
"""

import hashlib
import json
import math
from pathlib import Path


REQUIRED=("road_context.json","condition_history.jsonl","video_frames.jsonl")


def _number(value,label):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):
        raise ValueError("Missing finite "+label)
    return float(value)


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def _speed(velocity):
    if not isinstance(velocity,list) or len(velocity)!=3:
        raise ValueError("Missing Native 3D velocity")
    return math.sqrt(sum(_number(v,"velocity component")**2 for v in velocity))


def analyze(root:Path)->dict:
    root=Path(root);hashes={}
    for name in REQUIRED:
        path=root/name
        if not path.is_file():raise ValueError("Missing original source: "+name)
        hashes[name]=hashlib.sha256(path.read_bytes()).hexdigest()
    ctx=json.loads((root/"road_context.json").read_text())
    for key in ("native_map_id","ego_actor_id","road_id","lane_id",
                "road_surface_source","lane_width_source","traffic_source",
                "weather_source","sight_source","curvature_source",
                "braking_model_source"):
        if ctx.get(key) is None:raise ValueError("Missing sourced speed context: "+key)
    surface_ref=ctx["road_surface_source"]
    if not isinstance(surface_ref,dict) or not isinstance(surface_ref.get("path"),str):
        raise ValueError("Original surface document binding required")
    rel=Path(surface_ref["path"])
    if rel.is_absolute() or ".." in rel.parts or str(rel) in ("", "."):
        raise ValueError("Unsafe original surface document path")
    source=root/rel
    if not source.is_file() or not source.resolve().is_relative_to(root.resolve()):
        raise ValueError("Missing required source: surface.txt")
    if hashlib.sha256(source.read_bytes()).hexdigest()!=surface_ref.get("sha256"):
        raise ValueError("Original surface document hash changed")
    hashes[str(rel)]=surface_ref["sha256"]
    reaction=_number(ctx.get("diagnostic_reaction_time_s"),"diagnostic reaction time")
    decel=_number(ctx.get("diagnostic_braking_deceleration_mps2"),"diagnostic deceleration")
    if reaction<0 or decel<=0:raise ValueError("Invalid declared engineering braking model")
    rows,frames=_rows(root/"condition_history.jsonl"),_rows(root/"video_frames.jsonl")
    if len(rows)<2 or len(rows)!=len(frames):raise ValueError("Incomplete original condition history")
    previous=(-1,-math.inf);samples=[]
    for i,(row,frame) in enumerate(zip(rows,frames)):
        fid,time=row.get("frame"),_number(row.get("time_s"),"time")
        if type(fid) is not int or fid<=previous[0] or time<=previous[1]:
            raise ValueError("Nonmonotone original history")
        previous=fid,time
        if frame.get("video_frame")!=i or frame.get("carla_frame")!=fid or frame.get("time_s")!=time:
            raise ValueError("Original frame join failed")
        if row.get("ego_actor_id")!=ctx["ego_actor_id"] or row.get("road_id")!=ctx["road_id"] or row.get("lane_id")!=ctx["lane_id"]:
            raise ValueError("Ego source road/actor mismatch")
        if row.get("ego_velocity_source")!="actor.get_velocity":
            raise ValueError("Ego Native velocity source missing")
        speed=_speed(row.get("ego_velocity_mps"))
        lane_width=_number(row.get("lane_width_m"),"lane width")
        sight=_number(row.get("sight_distance_m"),"sight distance")
        curvature=_number(row.get("curvature_per_m"),"curvature")
        precip=_number(row.get("precipitation_percent"),"precipitation")
        fog={}
        if 'fog_density_percent' in row or 'fog_distance_m' in row:
            density=_number(row.get('fog_density_percent'),'fog density')
            distance=_number(row.get('fog_distance_m'),'fog distance')
            if not 0<=density<=100 or distance<0:
                raise ValueError('Invalid frame-specific fog readback')
            fog={'fog_density_percent':density,'fog_distance_m':distance}
        if lane_width<=0 or sight<0 or curvature<0 or not 0<=precip<=100:
            raise ValueError("Invalid frame-specific highway condition")
        if row.get("surface") not in ("dry","wet","ice_or_snow"):
            raise ValueError("Surface condition not source-resolved")
        if (row.get("surface_source")!=surface_ref or row.get("physical_surface_verified") is not False
                or row.get("weather_source")!="world.get_weather" or not row.get("sight_ray_source")
                or not row.get("curvature_source")):
            raise ValueError("Original frame condition source join failed")
        traffic=row.get("surrounding_traffic")
        if not isinstance(traffic,list):raise ValueError("Missing surrounding-traffic inventory")
        actors=[]
        for other in traffic:
            if not other.get("actor_id") or other.get("velocity_source")!="actor.get_velocity":
                raise ValueError("Surrounding-traffic Native source missing")
            gap=_number(other.get("longitudinal_body_gap_m"),"traffic body gap")
            actors.append({"actor_id":other["actor_id"],"speed_mps":_speed(other.get("velocity_mps")),
                           "longitudinal_body_gap_m":gap})
        stop_distance=speed*reaction+speed*speed/(2*decel)
        samples.append({"frame":fid,"time_s":time,"ego_speed_mps":speed,
                        "lane_width_m":lane_width,"surface":row["surface"],
                        "precipitation_percent":precip,"sight_distance_m":sight,
                        **fog,
                        "curvature_per_m":curvature,"surrounding_traffic":actors,
                        "diagnostic_stopping_distance_m":stop_distance,
                        "diagnostic_stop_distance_exceeds_sight":stop_distance>sight})
    return {"format":"worker-basic-speed-conditions-observations","sources":hashes,
            "surface_source_path":str(rel),
            "engineering_model":{"reaction_time_s":reaction,"braking_deceleration_mps2":decel,
                                 "source":ctx["braking_model_source"],"legal_threshold":False},
            "samples":samples,"reasonable_or_proper_judgment":"unresolved",
            "legal_conclusion":"unresolved"}

"""Independent saved-source and controlled-comparison checks for C179789.

This audit verifies provenance and declared changes. It never makes a legal or
physical-acceptance decision from synthetic or unreviewed sources.
"""

import hashlib
import json
import math
import argparse
from pathlib import Path

ASSIGNMENT = 'testing__C179789__NRS-484B-600-1a__motor_vehicle_driver'
EXACT_CASES = {ASSIGNMENT + '__' + suffix for suffix in (
    'dry_open_traffic', 'wet_same_traffic', 'narrow_same_traffic',
    'dense_traffic', 'low_visibility', 'ice_or_snow', 'dry_4mps', 'dry_6mps')}
CAMERAS = ('overview.mkv', 'approach.mkv', 'reference_corner.mkv',
           'driver_reference.mkv')
SOURCE_NAMES = ('road_context.json', 'condition_history.jsonl',
                'video_frames.jsonl')


def _sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _json(path):
    return json.loads(path.read_text())


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def audit_delivery(attempt, analysis_path):
    attempt = Path(attempt)
    result = _json(attempt / 'result.json')
    analysis = _json(Path(analysis_path))
    config = _json(attempt / 'config.json')
    case = config['selected_case_id']
    if case not in EXACT_CASES or case != result.get('case_id') or case != analysis.get('case_id'):
        raise ValueError('Exact saved case join failed')
    if result.get('physical_acceptance_claimed') is not False or analysis.get('physical_acceptance_claimed') is not False:
        raise ValueError('Unreviewed physical acceptance claimed')
    if (result.get('measured_values', {}).get('reasonable_or_proper_judgment') != 'unresolved'
            or analysis.get('legal_conclusion') != 'unresolved'):
        raise ValueError('Unsupported reasonable-or-proper conclusion')
    sources = result.get('source_hashes')
    if sources != analysis.get('source_report', {}).get('sources') or not isinstance(sources, dict):
        raise ValueError('Saved source-hash inventories differ')
    for name, digest in sources.items():
        rel = Path(name)
        path = (attempt / rel).resolve()
        if rel.is_absolute() or '..' in rel.parts or not path.is_relative_to(attempt.resolve()):
            raise ValueError('Unsafe saved source path')
        if not path.is_file() or _sha(path) != digest:
            raise ValueError('Saved original source changed: ' + name)
    if not set(SOURCE_NAMES).issubset(sources):
        raise ValueError('Missing required condition source hashes')
    capture = attempt / 'capture/evidence.jsonl'
    if not capture.is_file() or _sha(capture) != result.get('capture_evidence_sha256'):
        raise ValueError('Saved capture evidence changed')
    for camera in CAMERAS:
        if camera not in result.get('video_references', []) or not (attempt / camera).is_file():
            raise ValueError('Saved original camera missing: ' + camera)
    rows = _rows(attempt / 'condition_history.jsonl')
    frames = _rows(attempt / 'video_frames.jsonl')
    channel = _rows(attempt / 'speed-channel.jsonl')
    samples = analysis['source_report']['samples']
    if len(rows) < 2 or not (len(rows) == len(frames) == len(channel) == len(samples)):
        raise ValueError('Original frame or speed-channel count differs')
    target = config['condition_target']
    for index, (row, frame, speed_row, sample) in enumerate(zip(rows, frames, channel, samples)):
        if (frame.get('video_frame') != index or frame.get('carla_frame') != row.get('frame')
                or sample.get('frame') != row.get('frame') or sample.get('time_s') != row.get('time_s')):
            raise ValueError('Independent original frame join failed')
        velocity = row.get('ego_velocity_mps')
        if not isinstance(velocity, list) or len(velocity) != 3 or any(
                type(value) not in (int, float) or not math.isfinite(value) for value in velocity):
            raise ValueError('Original Native velocity invalid')
        speed = math.sqrt(sum(value * value for value in velocity))
        if (abs(speed_row.get('value', -1) - speed) > 1e-9
                or abs(sample.get('ego_speed_mps', -1) - speed) > 1e-9
                or speed_row.get('time_s') != row.get('time_s')):
            raise ValueError('Derived speed differs from original velocity')
        if row.get('surface') != target['surface']:
            raise ValueError('Surface target differs from original frame')
        for key, value in (('lane_width_m', row['lane_width_m']),
                           ('longitudinal_body_gap_m', row['surrounding_traffic'][0]['longitudinal_body_gap_m']),
                           ('sight_distance_m', row['sight_distance_m']),
                           ('precipitation_percent', row['precipitation_percent'])):
            if not target[key][0] <= value <= target[key][1]:
                raise ValueError('Condition target differs from original frame: ' + key)
        for key in ('fog_density_percent', 'fog_distance_m'):
            if key in target:
                value = row[key]
                if sample.get(key) != value or not target[key][0] <= value <= target[key][1]:
                    raise ValueError('Fog target differs from original frame: ' + key)
    matched = {check['target']: check['matched'] for check in result.get('target_checks', [])}
    if any(not matched.get(key, False) for key in (*target.keys(), 'sampled_peak_speed_mps')):
        raise ValueError('Saved condition or speed target did not match')
    return {'format': 'worker-c179789-independent-delivery-audit', 'case_id': case,
            'passed': True, 'source_hashes': sources, 'frame_count': len(rows),
            'camera_sha256': {name: _sha(attempt / name) for name in CAMERAS},
            'physical_acceptance_claimed': False, 'legal_conclusion': 'unresolved'}


def audit_comparison(attempts):
    """Check declared changes in all eight exact constructions."""
    if set(attempts) != {'dry_open_traffic', 'wet_same_traffic', 'dense_traffic',
                         'narrow_same_traffic', 'low_visibility', 'ice_or_snow',
                         'dry_4mps', 'dry_6mps'}:
        raise ValueError('Eight exact controlled comparison members required')
    docs = {}
    for suffix, root in attempts.items():
        root = Path(root)
        config = _json(root / 'config.json')
        road = _json(root / 'road_packet.json')
        if config['selected_case_id'] != ASSIGNMENT + '__' + suffix or road['case_id'] != config['selected_case_id']:
            raise ValueError('Controlled comparison case join failed')
        docs[suffix] = (config, road, _json(root / 'surface_packet.json'))
    dry, wet, dense, narrow, low, ice = (docs[key] for key in (
        'dry_open_traffic', 'wet_same_traffic', 'dense_traffic', 'narrow_same_traffic', 'low_visibility', 'ice_or_snow'))
    for other in (wet, dense, low, ice):
        for key in ('native_map_id', 'road_id', 'lane_id', 'ego_spawn',
                    'ego_target_speed_mps', 'vehicle_blueprint_id', 'lead_blueprint_id'):
            if other[1][key] != dry[1][key]:
                raise ValueError('Undeclared fixed road or ego change: ' + key)
    for key in ('native_map_id', 'lane_id', 'ego_target_speed_mps',
                'vehicle_blueprint_id', 'lead_blueprint_id'):
        if narrow[1][key] != dry[1][key]:
            raise ValueError('Undeclared narrow vehicle or control change: ' + key)
    for other in (wet, dense, narrow, low, ice):
        for key in ('rate_hz', 'duration_s', 'cameras', 'requested_speed_mps'):
            if other[0][key] != dry[0][key]:
                raise ValueError('Undeclared fixed capture change: ' + key)
    for suffix, speed in (('dry_4mps', 4), ('dry_6mps', 6)):
        config, road, surface = docs[suffix]
        if config['requested_speed_mps'] != speed or road['ego_target_speed_mps'] != speed:
            raise ValueError('Speed sweep setpoint mismatch: ' + suffix)
        if surface != dry[2] or road['weather_profile'] != dry[1]['weather_profile']:
            raise ValueError('Speed sweep changed fixed surface or weather: ' + suffix)
        for key in ('native_map_id', 'road_id', 'lane_id', 'ego_spawn', 'lead_spawn',
                    'lead_target_speed_mps', 'vehicle_blueprint_id', 'lead_blueprint_id'):
            if road[key] != dry[1][key]:
                raise ValueError('Speed sweep changed fixed site or traffic: ' + key)
        for key in ('rate_hz', 'duration_s', 'cameras', 'condition_target'):
            if config[key] != dry[0][key]:
                raise ValueError('Speed sweep changed fixed capture or condition: ' + key)
    if wet[1]['lead_spawn'] != dry[1]['lead_spawn'] or wet[1]['lead_target_speed_mps'] != dry[1]['lead_target_speed_mps']:
        raise ValueError('Wet case changed fixed traffic')
    if wet[2]['surface'] != 'wet' or dry[2]['surface'] != 'dry' or wet[1]['weather_profile'] == dry[1]['weather_profile']:
        raise ValueError('Wet case lacks declared surface/weather change')
    if dense[2] != dry[2] or dense[1]['weather_profile'] != dry[1]['weather_profile']:
        raise ValueError('Dense case changed fixed surface/weather')
    if dense[1]['lead_spawn'] == dry[1]['lead_spawn'] or dense[1]['lead_target_speed_mps'] == dry[1]['lead_target_speed_mps']:
        raise ValueError('Dense case lacks declared traffic change')
    for key in ('lead_spawn', 'lead_target_speed_mps'):
        if low[1][key] != dry[1][key]:
            raise ValueError('Low-visibility case changed fixed traffic')
    if low[2] != dry[2]:
        raise ValueError('Low-visibility case changed fixed surface')
    dry_weather, low_weather = dry[1]['weather_profile'], low[1]['weather_profile']
    for key in ('cloudiness', 'precipitation', 'wetness', 'sun_altitude_angle'):
        if low_weather[key] != dry_weather[key]:
            raise ValueError('Low-visibility case changed fixed weather: ' + key)
    if (low_weather['fog_density'] == dry_weather['fog_density'] or
            low_weather['fog_distance'] == dry_weather['fog_distance'] or
            low[0]['condition_target'].get('fog_density_percent') != [70, 90] or
            low[0]['condition_target'].get('fog_distance_m') != [10, 30]):
        raise ValueError('Low-visibility case lacks declared fog change')
    for key in ('lead_spawn', 'lead_target_speed_mps'):
        if ice[1][key] != dry[1][key]:
            raise ValueError('Ice/snow case changed fixed traffic')
    if (ice[2]['surface'] != 'ice_or_snow' or
            ice[2]['road_id'] != ice[1]['road_id'] or
            ice[1]['weather_profile'] == dry_weather or
            ice[0]['condition_target']['precipitation_percent'] != [70, 90]):
        raise ValueError('Ice/snow case lacks declared surface/weather change')
    def relative_gap(packet):
        return [packet['lead_spawn'][axis] - packet['ego_spawn'][axis]
                for axis in ('x', 'y', 'z')]
    if (narrow[2]['surface'] != dry[2]['surface'] or
            narrow[2]['road_id'] != narrow[1]['road_id'] or
            narrow[1]['road_id'] == dry[1]['road_id'] or
            narrow[1]['ego_spawn'] == dry[1]['ego_spawn'] or
            narrow[1]['weather_profile'] != dry[1]['weather_profile'] or
            relative_gap(narrow[1]) != relative_gap(dry[1]) or
            narrow[1]['lead_target_speed_mps'] != dry[1]['lead_target_speed_mps']):
        raise ValueError('Narrow case changed fixed surface, weather or traffic')
    if (narrow[0]['condition_target']['lane_width_m'] != [2.5, 2.9]
            or dry[0]['condition_target']['lane_width_m'] != [3, 4]):
        raise ValueError('Narrow case lacks declared lane-width change')
    return {'format': 'worker-c179789-independent-comparison-audit', 'passed': True,
            'cases': [ASSIGNMENT + '__' + key for key in attempts],
            'physical_realization_verified': False}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--attempt')
    parser.add_argument('--analysis')
    parser.add_argument('--dry')
    parser.add_argument('--wet')
    parser.add_argument('--dense')
    parser.add_argument('--narrow')
    parser.add_argument('--low')
    parser.add_argument('--ice')
    parser.add_argument('--dry4')
    parser.add_argument('--dry6')
    args = parser.parse_args()
    if args.attempt and args.analysis and not any((args.dry, args.wet, args.dense, args.narrow, args.low, args.ice, args.dry4, args.dry6)):
        receipt = audit_delivery(args.attempt, args.analysis)
    elif all((args.dry, args.wet, args.dense, args.narrow, args.low, args.ice, args.dry4, args.dry6)) and not any((args.attempt, args.analysis)):
        receipt = audit_comparison({'dry_open_traffic': args.dry,
                                    'wet_same_traffic': args.wet,
                                    'dense_traffic': args.dense,
                                    'narrow_same_traffic': args.narrow,
                                    'low_visibility': args.low,
                                    'ice_or_snow': args.ice,
                                    'dry_4mps': args.dry4,
                                    'dry_6mps': args.dry6})
    else:
        parser.error('Supply an attempt and analysis, or eight controlled source roots')
    print(json.dumps(receipt, indent=2))


if __name__ == '__main__':
    main()

